/*
  Fandex sample values. Written by running the product's own engine
  (fandex src/lib/engine.ts: compute, summarize, curve, verdict) over its own
  data file (src/data/data.json, generated 2026-11-17), with the default
  weights of 50, 30 and 20, no recency weighting, every league counted and seasons in progress left out.

  The fan is someone born in 2005 who follows the Denver clubs: one in each
  of the four big leagues, and the Rapids in MLS. Records are
  the real regular season records from the product's feeds. Nothing is edited.
  A season is [year it started, z-score against that year's league, flag], where
  the flag is 1 for a title and 2 for a lost final.
*/

export type Chip = { abbr: string; color: string; ink: string };
export type Cell = [number, number, number];
export type Row = Chip & {
  rank: number; leagueRank: number; name: string; nick: string; league: string; metro: string;
  seasons: number; w: number; l: number; t: number; pct: number; z: number; avgZ: number;
  elite: number; dud: number; titles: number; finalsLost: number; index: number;
};
export type Mine = Row & { series: Cell[] };
export type GridRow = Chip & { leagueRank: number; nick: string; name: string; w: number; l: number; t: number; series: Cell[] };
export type Metro = { rank: number; name: string; index: number; pct: number; titles: number; finalsLost: number; x: number; y: number; teams: (Chip & { current: boolean })[] };
export type Spell = Chip & { name: string; league: string; pct: number; titles: number; index: number; current: boolean; first: number; last: number; seasons: number; rank: number; franchiseSeasons: number; now: string };

